using Finance.Core;
using System.Data;
namespace Finance.Desktop;
internal partial class MainForm:Form
{
    readonly Engine engine;readonly Panel content=new(){Dock=DockStyle.Fill,Padding=new Padding(18)};readonly Label status=new(){Dock=DockStyle.Bottom,Height=28,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(10,0,0,0)};
    readonly System.Windows.Forms.Timer backupTimer=new(){Interval=60000};DateTime lastBackup=DateTime.MinValue;
    DateTimePicker from=Ui.Date(new DateTime(DateTime.Today.Month>=4?DateTime.Today.Year:DateTime.Today.Year-1,4,1)),to=Ui.Date();
    public MainForm(Engine e){engine=e;using(var d=e.Open()){string fy=Value.Text(d.Scalar("SELECT Value FROM Setting WHERE Key='FinancialYear'"));if(fy.Length>=4&&int.TryParse(fy[..4],out int start)&&start is >=1900 and <=2199){from.Value=new DateTime(start,4,1);to.Value=new DateTime(start+1,3,31);}}Text="Business Finance | Acceptance build 0.2.0";Icon=System.Drawing.Icon.ExtractAssociatedIcon(Environment.ProcessPath!);WindowState=FormWindowState.Maximized;MinimumSize=new(1050,720);Font=new("Segoe UI",10);BackColor=Ui.Back;
        var nav=new FlowLayoutPanel{Dock=DockStyle.Left,Width=195,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(10),BackColor=Ui.Navy};nav.Controls.Add(new Label{Text="BUSINESS\nFINANCE",ForeColor=Color.White,Font=new("Segoe UI",18,FontStyle.Bold),Height=80,Width=170});
        foreach(var name in new[]{"DASHBOARD","SALES","PURCHASE","RECEIPT","PAYMENT","BANK TRANSFER","SITE EXPENSE","PAYROLL","EMPLOYEE LOAN","FD","BG","BUSINESS LOAN","REPORTS","MASTERS","SETTINGS","BACKUP / RESTORE","HELP / ABOUT"}){var b=Ui.Button(name,()=>Navigate(name),168);b.Height=35;b.BackColor=Ui.Navy;b.ForeColor=Color.White;b.TextAlign=ContentAlignment.MiddleLeft;b.FlatAppearance.BorderSize=0;nav.Controls.Add(b);}Controls.Add(content);Controls.Add(nav);Controls.Add(status);
        backupTimer.Tick+=(_,_)=>AutoBackup();backupTimer.Start();FormClosed+=(_,_)=>backupTimer.Dispose();Navigate("DASHBOARD");}
    internal void VerifyNavigationForSmoke(List<string> results)
    {
        foreach(string module in new[]{"DASHBOARD","SALES","PURCHASE","RECEIPT","PAYMENT","BANK TRANSFER","SITE EXPENSE","PAYROLL","EMPLOYEE LOAN","FD","BG","BUSINESS LOAN","REPORTS","MASTERS","SETTINGS","BACKUP / RESTORE","HELP / ABOUT"})
        {
            Navigate(module);
            content.CreateControl();
            content.PerformLayout();
            results.Add("PASS | Navigation: " + module);
        }
    }
    void Footer(){using var d=engine.Open();string backup=Value.Text(d.Scalar("SELECT TimeUtc FROM BackupHistory ORDER BY Id DESC LIMIT 1"));status.Text=$"{Ui.Credit} | v0.2.0 | FY {Value.FY(Ui.Day(to))} | {engine.UserName} | Database: Connected | Last backup: {(DateTimeOffset.TryParse(backup,out var dt)?dt.ToLocalTime().ToString("dd-MM-yyyy HH:mm"):"Not yet")}";}
    void Navigate(string name){engine.Authenticate();content.Controls.Clear();Footer();switch(name){case "DASHBOARD":Dashboard();break;case "SALES":Register("Sales Register",()=>Invoice("Sales"));break;case "PURCHASE":Register("Purchase Register",()=>Invoice("Purchase"));break;case "RECEIPT":Register("Transaction Register",()=>Movement(true),"Receipt");break;case "PAYMENT":Register("Transaction Register",()=>Movement(false),"Payment");break;case "BANK TRANSFER":Register("Transaction Register",Transfer,"Bank Transfer");break;case "SITE EXPENSE":Register("Expense Register",SiteExpense,"Site Expense");break;case "PAYROLL":Register("Payroll Register",Payroll);break;case "EMPLOYEE LOAN":Register("Employee Loan Register",()=>Instrument("Employee Loan"));break;case "FD":Register("FD Register",()=>Instrument("FD"));break;case "BG":Register("BG Register",()=>BG());break;case "BUSINESS LOAN":Register("Business Loan Register",()=>Instrument("Business Loan"));break;case "REPORTS":ReportChooser();break;case "MASTERS":Masters();break;case "SETTINGS":Settings();break;case "BACKUP / RESTORE":BackupScreen();break;default:About();break;}}
    FlowLayoutPanel Bar()=>new(){Dock=DockStyle.Top,Height=48,Padding=new Padding(3),WrapContents=false,AutoScroll=true};
    void Title(string title,string subtitle=""){var p=new Panel{Dock=DockStyle.Top,Height=70};p.Controls.Add(new Label{Text=title,Font=new("Segoe UI",20,FontStyle.Bold),ForeColor=Ui.Navy,Dock=DockStyle.Top,Height=38});p.Controls.Add(new Label{Text=subtitle,Dock=DockStyle.Bottom,Height=24,ForeColor=Color.DimGray});content.Controls.Add(p);}
    List<Choice> Choices(string table,string filter="1=1"){using var d=engine.Open();string name=table is "Instrument" or "BG"?"Number":table=="PayrollRow"?"Id":"Name";return d.Table($"SELECT Id,{name} FROM {table} WHERE {filter} ORDER BY 2").Rows.Cast<DataRow>().Select(r=>new Choice(Value.Long(r[0]),Value.Text(r[1]))).ToList();}
    void Dashboard(){var area=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};var values=engine.Dashboard(Ui.Day(from),Ui.Day(to));var links=new Dictionary<string,string>{["Sales"]="Sales Register",["Purchases"]="Purchase Register",["Customer Receivable"]="Customer Ledger",["Supplier Payable"]="Supplier Ledger",["Bank Balance"]="Bank Balances",["Cash Balance"]="Cash Book",["Salary Payable"]="Salary Payment Status",["Staff Advance Outstanding"]="Staff Advance Outstanding",["Employee Advance Outstanding"]="Employee Advance Outstanding",["Employee Loan Outstanding"]="Employee Loan Register",["Total FD"]="FD Register",["FD Under Lien"]="FD Lien",["Active BG Amount"]="BG Register",["Business Loan Outstanding"]="Business Loan Register"};foreach(var (key,amount) in values){var card=Ui.Button(key+"\nINR "+Value.Display(amount),()=>{content.Controls.Clear();Register(links[key]);},245);card.Height=100;card.TextAlign=ContentAlignment.MiddleLeft;card.Padding=new Padding(12);card.Font=new("Segoe UI",12,FontStyle.Bold);area.Controls.Add(card);}area.Controls.Add(Ui.Button("Open alert centre",()=>{content.Controls.Clear();Register("Alerts");},245));content.Controls.Add(area);var dates=Bar();dates.Controls.Add(new Label{Text="Activity from",AutoSize=true,Padding=new Padding(0,8,0,0)});dates.Controls.Add(from);dates.Controls.Add(new Label{Text="Balances as at",AutoSize=true,Padding=new Padding(0,8,0,0)});dates.Controls.Add(to);dates.Controls.Add(Ui.Button("Refresh",()=>Navigate("DASHBOARD")));content.Controls.Add(dates);using var d=engine.Open();Title(Value.Text(d.Scalar("SELECT Name FROM Company WHERE Id=1")) is var name && name!=""?name:"Welcome — configure your company","Enter once. Calculate automatically. Post correctly. Reconcile everywhere.");}
    void ReportChooser(){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};foreach(string name in Engine.ReportNames)panel.Controls.Add(Ui.Button(name,()=>{content.Controls.Clear();Register(name);},240));content.Controls.Add(panel);Title("Reports","All balances derive from the central posting ledger.");}
    void Register(string report,Action? add=null,string searchDefault="")
    {
        var grid=Ui.Grid();var bar=Bar();var actions=Bar();var search=new TextBox{Width=190,PlaceholderText="Search number, party, status…",Text=searchDefault};int page=0;var pageLabel=new Label{AutoSize=true,Padding=new Padding(5,9,0,0)};DataTable raw=new();
        void Load(){raw=engine.Report(report,Ui.Day(from),Ui.Day(to),search.Text,page);grid.DataSource=Engine.DisplayTable(raw);pageLabel.Text=$"Page {page+1} • {raw.Rows.Count} records";Footer();}
        long Selected(){Value.Require(grid.CurrentRow!=null,"Select a record first.");return long.TryParse(Value.Text(grid.CurrentRow!.Cells["Id"].Value),out var id)?id:throw new BusinessException("Select a record with a numeric reference.");}
        DataRow Row(){long id=Selected();return raw.Rows.Cast<DataRow>().First(r=>Value.Long(r["Id"])==id&&(report!="Alerts"||Value.Text(r["Entity"])==Value.Text(grid.CurrentRow!.Cells["Entity"].Value)));}
        void Refresh(){Load();}
        if(add!=null)bar.Controls.Add(Ui.Button("+ New entry",()=>{add();Refresh();}));bar.Controls.Add(from);bar.Controls.Add(to);bar.Controls.Add(search);bar.Controls.Add(Ui.Button("Search",()=>{page=0;Load();},85));bar.Controls.Add(Ui.Button("Previous",()=>{if(page>0)page--;Load();},85));bar.Controls.Add(Ui.Button("Next",()=>{if(raw.Rows.Count==200)page++;Load();},65));bar.Controls.Add(pageLabel);
        actions.Controls.Add(Ui.Button("Details / document",()=>ShowDocument(report,Selected(),Row()),155));
        actions.Controls.Add(Ui.Button("Export Excel",()=>ExportReport(report,search.Text),115));actions.Controls.Add(Ui.Button("Print / PDF",()=>PrintReport(report,search.Text),110));
        if(report is "Sales Register" or "Purchase Register"){
            if(report=="Sales Register")actions.Controls.Add(Ui.Button("Apply advance",()=>{using var d=engine.Open();long invoice=Selected();long party=d.N("SELECT PartyId FROM Invoice WHERE Id=@p0",invoice);using var f=new Entry("Apply customer advance to invoice");f.Add("Day","Adjustment date","date");f.Add("Amount","Amount (INR)","money");f.Add("Reference","Reference");f.Finish(x=>engine.ApplyCustomerAdvance(x.D("Day"),party,[new(invoice,x.N("Amount"))],x.S("Reference")));f.ShowDialog(this);Refresh();}));actions.Controls.Add(Ui.Button("Post draft",()=>{Confirm("Post the selected invoice?",()=>engine.PostInvoice(Selected()));Refresh();}));actions.Controls.Add(Ui.Button("Cancel invoice",()=>{ReasonDate("Cancel invoice",(day,reason)=>engine.CancelInvoice(Selected(),day,reason));Refresh();}));actions.Controls.Add(Ui.Button("Attachments",()=>Attachments("Invoice",Selected())));
        }else if(report=="Transaction Register"){
            actions.Controls.Add(Ui.Button("Reverse",()=>{ReasonDate("Reverse voucher",(day,reason)=>engine.Reverse(Selected(),day,reason));Refresh();}));actions.Controls.Add(Ui.Button("Attachments",()=>Attachments("Voucher",Selected())));
        }else if(report is "Payroll Register" or "Salary Payment Status")actions.Controls.Add(Ui.Button("Reopen payroll",()=>{long id=Value.Long(Row()["PayrollId"]);ReasonDate("Reopen payroll",(_,reason)=>engine.ReopenPayroll(id,reason));Refresh();}));
        else if(report is "FD Register" or "FD Maturity"){
            actions.Controls.Add(Ui.Button("Close / renew FD",()=>{CloseFD(Selected());Refresh();},145));actions.Controls.Add(Ui.Button("Release lien",()=>{ReasonDate("Release FD lien",(day,reason)=>engine.ReleaseFD(Selected(),day,reason));Refresh();}));actions.Controls.Add(Ui.Button("Attachments",()=>Attachments("Instrument",Selected())));
        }else if(report is "Employee Loan Register" or "Business Loan Register"){
            actions.Controls.Add(Ui.Button("Recovery / EMI terms",()=>{using var f=new Entry("Update loan terms");f.Add("Rate","Interest %","percent");f.Add("EMI","Monthly recovery / EMI (INR)","money");f.Add("Next","Next recovery date","date");f.Add("Reason","Reason","multiline");f.Finish(x=>engine.LoanTerms(Selected(),x.Dec("Rate"),x.N("EMI"),x.D("Next"),x.S("Reason")));f.ShowDialog(this);Refresh();},165));actions.Controls.Add(Ui.Button("Close settled loan",()=>{ReasonDate("Close loan",(day,reason)=>engine.CloseLoan(Selected(),day,reason));Refresh();},145));actions.Controls.Add(Ui.Button("Attachments",()=>Attachments("Instrument",Selected())));
        }else if(report is "BG Register" or "BG Expiry"){
            actions.Controls.Add(Ui.Button("Amend / dispatch",()=>{BG(Selected());Refresh();},145));actions.Controls.Add(Ui.Button("Link FD",()=>{LinkFD(Selected());Refresh();},90));actions.Controls.Add(Ui.Button("Close BG",()=>{ReasonDate("Close BG",(day,reason)=>engine.CloseBG(Selected(),day,reason));Refresh();},95));actions.Controls.Add(Ui.Button("Attachments",()=>Attachments("BG",Selected())));
        }else if(report=="Bank Reconciliation"){
            actions.Controls.Add(Ui.Button("Match",()=>{ReasonDate("Match bank statement",(day,reason)=>engine.Reconcile(Selected(),day,reason,true));Refresh();}));actions.Controls.Add(Ui.Button("Unmatch",()=>{ReasonDate("Remove reconciliation",(day,reason)=>engine.Reconcile(Selected(),day,reason,false));Refresh();}));
        }else if(report=="Alerts")actions.Controls.Add(Ui.Button("Open alert",()=>OpenAlert(Row())));
        content.Controls.Add(grid);content.Controls.Add(actions);content.Controls.Add(bar);Title(report,"Dates: DD-MM-YYYY • INR • Export/print includes all filtered pages • Invoice settlements reflect the selected end date.");Load();grid.CellDoubleClick+=(_,_)=>Ui.Run(()=>{if(report=="Alerts")OpenAlert(Row());else ShowDocument(report,Selected(),Row());});
    }
    void Confirm(string question,Action action){if(MessageBox.Show(question,"Confirm",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)action();}
    void ReasonDate(string title,Action<int,string> action){using var f=new Entry(title);f.Add("Day","Effective date","date");f.Add("Reason","Reason / reference","multiline");f.Finish(x=>{Value.Require(!string.IsNullOrWhiteSpace(x.S("Reason")),"A reason is required.");Confirm(title+"?",()=>action(x.D("Day"),x.S("Reason")));});f.ShowDialog(this);}
    void OpenAlert(DataRow row){string entity=Value.Text(row["Entity"]);long id=Value.Long(row["Id"]);using var d=engine.Open();if(entity=="Invoice")ShowDocument("Sales Register",id,d.Row("SELECT * FROM Invoice WHERE Id=@p0",id));else if(entity=="PayrollRow")ShowDocument("Payroll Register",id,d.Row("SELECT * FROM PayrollRow WHERE Id=@p0",id));else if(entity=="BG")BG(id);else ShowDocument("Instrument",id,d.Row("SELECT * FROM Instrument WHERE Id=@p0",id));}
    void About(){using var d=engine.Open();var p=new Label{Dock=DockStyle.Fill,Padding=new Padding(30),Font=new("Segoe UI",12),Text="BUSINESS FINANCE\n\nVersion 0.2.0 • Acceptance build\nDatabase version 2\nBuild date: 06-10-2026\n\n"+Value.Text(d.Scalar("SELECT Name FROM Company WHERE Id=1"))+"\n\n"+Ui.Credit+"\nCopyright © 2026 Bikash Ranjan Nayak\n\nLocal single-user application. Data folder:\n"+System.IO.Path.GetDirectoryName(engine.Path)+"\n\nUse Masters → Company before invoicing.\nOpening balances: Settings → Opening balance.\nActual bank movements: Receipt / Payment.\nPrint to PDF uses Microsoft Print to PDF.\n\nThis build requires Windows acceptance testing before live use.\nSee RELEASE_NOTES.md for the remaining release gates."};content.Controls.Add(p);Title("About / Help");}
}
